export function entropyScoringModule(reasoningChains) {
  return reasoningChains.map(chain => {
    const entropy = calculateEntropy(chain);
    return { chain, score: 1 - entropy };
  });
}

function calculateEntropy(chain) {
  const probabilities = chain.map(step => step.probability);
  return -probabilities.reduce((sum, p) => sum + p * Math.log2(p), 0);
}